(function(){"use strict";var g=window.RH_WS=[],u=["\\(\\s*[A-Z][^)]*\\d{4}[a-z]?\\s*\\)|et al|doi|https?:","You cite your sources in the text.","Cite the sources you used in the text, for example (Allott and Mindorff, 2014)."],w=["\\b(I|my|me)\\b","You explain your own reason for choosing the topic.","Say why this matters to you: an observation, a question, an experience."],p=["\\d","You quote numbers from your data.","Quote numbers from your data (means with units)."],f=["because|due to|as a result|so that|this means","You explain your reasoning.","Explain why, not just what (use “because…”)."],v=["repeat|trial|replicate|five times|5 times|three times","You plan repeats.","Say how many times you repeat each level, and why."],l=function(e,t,o,b){var r=((e.a[t]||{})[o]||[]).filter(function(a){return a!==""&&a!=null&&isFinite(+a)}).map(Number);return r.length>=2?{v:r,own:!0}:{v:b[o].slice(),own:!1}},x={type:"classify",k:"evcls",q:"Sort these weaknesses: what kind of problem is each one?",cats:["Random error","Systematic error","Limitation of the design or scope"],items:[["Readings at the same level vary between trials.",0],["The stopwatch was started about a second late every time.",1],["Only one species (or enzyme) was tested, so the conclusion cannot be generalised.",2],["The thermometer always reads 1 °C higher than the true temperature.",1],["The interval between IV values is too wide to locate the optimum.",2],["Some readings were taken by eye from a moving scale.",0]],why:"Random errors scatter repeats (reduce them with more repeats and better instruments). Systematic errors shift every reading the same way (calibrate, change the procedure). Design limitations restrict what you can conclude (change the range, interval or scope).",hint:"Ask: does the problem scatter the data, shift all of it, or limit what you can claim?"},q={type:"mcq",k:"ebmcq",q:"The error bars (± 1 SD) of two neighbouring points overlap a lot. What can you say?",opts:["The two means are certainly different.","The difference may not be significant: check it with a statistical test.","One of the points must be an anomaly.","The graph is drawn wrongly."],a:1,why:"Overlapping SD bars suggest the difference could be due to variation between repeats. A statistical test gives the evidence; overlap alone does not prove there is no difference."},C={type:"mcq",k:"repmcq",q:"Why do you repeat each level of the independent variable several times?",opts:["To make the results more accurate.","To assess the variation (reliability) of the results, spot anomalies and use a mean.","Because the IB requires exactly five repeats.","To get a bigger difference between levels."],a:1,why:"Repeats show how much results vary, let you identify anomalies, and give a mean and an SD for statistics. They improve reliability (precision); they do not fix a systematic error, so they do not by themselves make the results more accurate."};function h(e){var t=e.ex,o=e.iv,b=e.levels[e.calc||0],r=function(a){return a?" "+a:""};g.push({id:e.id,group:"IA",subject:"Biology",target:"ia",title:e.title,summary:e.summary,sim:e.sim,download:e.download,minutes:e.minutes||120,sections:[{title:"Research question",guide:["A strong research question names the <b>independent variable</b> with its range and units, the <b>dependent variable</b> and how it is measured, the <b>organism or enzyme</b>, and the main <b>fixed conditions</b>. It should be answerable with your data.",e.rqGuide||""],example:{title:"Exemplar research question",text:t.rq,note:t.rqNote},tasks:[{type:"mcq",k:"rqmcq",q:"Which research question is the most focused?",opts:e.rqOpts,a:e.rqA,why:e.rqWhy},{type:"rq",k:"rq",label:"Your research question",tip:"The checker scores it as you type. Aim for a strong question before you collect data.",map:"rq.text"}]},{title:"Context and background",guide:["<b>Personal engagement</b>: explain in a few sentences why you chose this question (an observation, a class practical, a real-world problem).","<b>Background</b>: explain the biology you need to make a prediction, in your own words, with sources cited in the text. Keep it relevant: only the theory your investigation uses."],example:{title:"Exemplar context and background",text:[t.engage,t.background],note:"It links a real observation to the question, then explains the mechanism step by step and cites two real sources."},tasks:[{type:"text",k:"engage",label:"Why did you choose this question?",min:30,rules:[w],map:"topic.interests"},{type:"text",k:"bg",label:"Background theory (with citations)",min:100,tall:!0,rules:e.bgRules.concat([u]),map:"topic.background"}]},{title:"Variables",guide:["The <b>independent variable (IV)</b> is what you change; the <b>dependent variable (DV)</b> is what you measure; <b>controlled variables</b> are kept the same because they would also affect the DV. For each one, say how and why."],example:{title:"Exemplar variables table",table:[["Variable","Type","How it is changed, measured or controlled"]].concat(t.vars)},tasks:[{type:"classify",k:"varcls",q:"Sort these variables for this investigation.",cats:["Independent","Dependent","Controlled","Not relevant"],items:e.varItems,why:"Correct. Each controlled variable needs a reason: how would it change the DV if it varied?",hint:"Only one variable is changed on purpose, and only one is measured."},{type:"text",k:"ivname",short:!0,label:"Independent variable (with units)",min:2,map:"variables.iv.name"},{type:"text",k:"levels",short:!0,label:"Levels of the IV you will test (range and interval)",min:3,rules:[p],map:"variables.iv.levels"},{type:"text",k:"dvname",short:!0,label:"Dependent variable (with units)",min:2,map:"variables.dv.name"},{type:"text",k:"dvmeas",label:"How you will measure the DV (instrument or readout, precision)",min:15,map:"variables.dv.measure"},{type:"text",k:"ctrl",label:"Controlled variables: value, how you keep it constant and why it matters",min:40,rules:[f],map:"variables.design.control"}]},{title:"Hypotheses",guide:["Write a <b>null hypothesis</b> (no significant difference or relationship) and an <b>alternative hypothesis</b> that predicts the direction and explains it with the theory from your background."],example:{title:"Exemplar hypotheses",text:["<b>H₀:</b> "+t.h0,"<b>H₁:</b> "+t.h1]},tasks:[{type:"text",k:"h0",label:"Null hypothesis (H₀)",min:10,rules:[["\\bno\\b|not","It states no difference or relationship.","H₀ should state that there is no significant difference or relationship."]],map:"hypothesis.null"},{type:"text",k:"h1",label:"Alternative hypothesis (H₁) with a scientific reason",min:25,rules:e.hypRules.concat([f]),map:"hypothesis.alt"}]},{title:"Method, safety and ethics",guide:["Write numbered steps someone else could follow and get the same data: settings, readings, number of repeats. When you use a simulator, say which one, what it models, and how you selected the data.","Even with a simulator, comment on safety, ethics and the environment: say what would apply in a real laboratory."],example:{title:"Exemplar method",text:"<ol>"+t.method.map(function(a){return"<li>"+a+"</li>"}).join("")+"</ol>",note:"Every setting is stated, the number of repeats is given, and the reason for the time window is explained."},tasks:[C,{type:"text",k:"method",label:"Your method (numbered steps)",min:80,tall:!0,rules:[v,p,["simulat|model|software|virtual","You name the simulator.","Name the simulator you used and what it models.","mid"]],map:"method.collection"},{type:"text",k:"safety",label:"Safety, ethics and environment",min:25,rules:[["safe|hazard|risk|irritant|goggle|eye","You consider safety.","Consider safety (in the simulation and in a real lab)."],["ethic|organism|living|animal|consent","You consider ethics.","Consider ethics (living organisms, people)."],["environment|waste|dispos","You consider the environment.","Consider the environment (waste, disposal)."]],map:"method.safety"}]},{title:"Collect your data with the simulator",guide:e.simGuide,tasks:[{type:"data",k:"raw",label:"Raw data table",tip:"Type each reading as you collect it. The processed table (mean, SD, SE) updates automatically. You can practise with the exemplar data, but your IA must use data you collect yourself.",iv:o,ivUnit:e.ivUnit,dv:e.dv,dvUnit:e.dvUnit,levels:e.levels,trials:e.trials||5,example:e.example},{type:"text",k:"obs",label:"Qualitative observations (what you saw during the runs)",min:15}]},{title:"Process the data and test it",guide:["Calculate the mean and a measure of spread for each level. Show one sample calculation. Then choose a statistical test that fits your design, and explain the result in words."],example:{title:"Exemplar sample calculation",text:t.calc},tasks:[{type:"num",k:"mean0",q:"Calculate the mean of your trials at "+o.toLowerCase()+" = "+b+r(e.ivUnit)+". (No data yet? Use the exemplar values: "+e.example[e.calc||0].join(", ")+".)",unit:e.dvUnit,a:function(a,i){return i.mean(l(a,"raw",e.calc||0,e.example).v)},work:function(a,i){var s=l(a,"raw",e.calc||0,e.example).v;return"Mean = ("+s.join(" + ")+") ÷ "+s.length+" = "+i.sig(i.mean(s),4)+r(e.dvUnit)},hint:"Add the readings and divide by how many there are."},{type:"num",k:"half0",q:"Now the uncertainty of that mean as ± half the range: (largest − smallest) ÷ 2.",unit:e.dvUnit,a:function(a){var i=l(a,"raw",e.calc||0,e.example).v;return(Math.max.apply(null,i)-Math.min.apply(null,i))/2},tol:.006,work:function(a,i){var s=l(a,"raw",e.calc||0,e.example).v,m=Math.max.apply(null,s),y=Math.min.apply(null,s);return"("+m+" − "+y+") ÷ 2 = "+i.sig((m-y)/2,3)+r(e.dvUnit)}},{type:"num",k:"sd0",q:"And the sample standard deviation (SD) of the same trials. (Use a calculator or the Statistics lab.)",unit:e.dvUnit,a:function(a,i){return i.sd(l(a,"raw",e.calc||0,e.example).v)},work:function(a,i){var s=l(a,"raw",e.calc||0,e.example).v,m=i.mean(s);return"SD = √[Σ(x − mean)² ÷ (n − 1)] = √["+i.sig(s.reduce(function(y,k){return y+(k-m)*(k-m)},0),4)+" ÷ "+(s.length-1)+"] = "+i.sig(i.sd(s),3)+r(e.dvUnit)},hint:"Use n − 1 (the sample SD), as calculators’ s or σn−1 key does."},e.testMcq,{type:"stats",from:"raw",test:e.test,label:"The "+(e.test==="spearman"?"Spearman rank correlation":"one-way ANOVA")+" on your data",note:e.statsNote},{type:"text",k:"stats",label:"What the test shows (statistic, p-value and what it means for H₀)",min:25,rules:[["p\\s*[<>=]|p-value|p value","You quote the p-value.","Quote the p-value."],["reject|accept|retain|null|H₀|H0","You state the decision about H₀.","Say whether you reject the null hypothesis."]],map:"conclusion.stats"}]},{title:"Graph",guide:["Plot the mean of each level with error bars, axes labelled with quantities and units, and a figure number and title. For a trend across a numerical IV, a scatter graph with points (and a line or curve of best fit when justified) is usual."],tasks:[{type:"graph",from:"raw",label:"Graph of your processed data",title:e.graphTitle,line:e.line},q]},{title:"Conclusion",guide:["Answer the research question directly with numbers from your data (means with uncertainties), the trend, and the statistical result. Then explain the trend with the biology, and compare it with published values or accounts."],example:{title:"Exemplar conclusion",text:t.conclusion,note:"It quotes data with uncertainties, refers to the statistics, explains the mechanism and compares with sources."},tasks:[{type:"text",k:"concl",label:"Answer to the research question (with data)",min:60,tall:!0,rules:[p,["increase|decrease|rise|fall|peak|maximum|optimum|trend|correlat","You describe the trend.","Describe the trend or pattern."],["signific|p\\s*[<>=]","You refer to the statistics.","Refer to the statistical result."]],map:"conclusion.answer"},{type:"text",k:"mech",label:"Scientific explanation of the trend",min:50,rules:e.mechRules,map:"conclusion.mechanism"},{type:"text",k:"lit",label:"Comparison with published information",min:25,rules:[u],map:"conclusion.literature"}]},{title:"Evaluation",guide:["Identify the main weaknesses and limitations, say how much each one affects the conclusion, and suggest a realistic, specific improvement for each. Then suggest an extension: a new question that follows from your results."],example:{title:"Exemplar evaluation (extract)",table:[["Weakness or limitation","Effect on the conclusion","Improvement"]].concat(t.evals)},tasks:[x,{type:"text",k:"weak",label:"Your weaknesses and their effect on the conclusion",min:60,tall:!0,rules:[["major|minor|moderate|significant(ly)? affect|effect on|uncertain|reliab|valid","You judge how much each weakness matters.","Say how much each weakness affects your conclusion (major, moderate, minor)."]]},{type:"text",k:"improve",label:"Specific improvements",min:40,rules:[["\\d|instead|use a|replace|add|increase|measure","Your improvements are specific.","Make each improvement specific (what, how, what difference it makes)."]]},{type:"text",k:"ext",label:"An extension: a new question that follows from your results",min:15},{type:"info",html:'<p class="tip">Copy your weaknesses and improvements into the evaluation table in the IA Studio (stage “Evaluation”): it keeps one row per weakness.</p>'}]}]})}h({id:"ia-ph-enzyme",title:"pH and enzyme activity (amylase or catalase)",summary:"Your first IA assignment, stage by stage: how does pH affect the activity of amylase or catalase? Data come from the enzyme simulator. The exemplar is the complete teacher-created IA (about 3,000 words) you can download.",sim:["/simulations/enzyme/","enzyme activity simulator"],download:"ia-exemplar-ph-enzyme-activity.docx",minutes:180,iv:"pH",ivUnit:"",dv:"Initial rate",dvUnit:"mmol dm⁻³ min⁻¹",levels:[4,5,6,7,8,9,10],calc:3,test:"anova",graphTitle:"Effect of pH on the initial rate of catalase activity",example:[[.62,.64,.65,.63,.63],[2.19,2.15,2.16,2.14,2.2],[4.56,4.39,4.45,4.31,4.39],[5.47,5.66,5.61,5.68,5.55],[4.52,4.41,4.37,4.32,4.39],[2.18,2.15,2.22,2.22,2.19],[.63,.63,.65,.62,.63]],rqOpts:["How does pH affect enzymes?","What is the optimum pH of catalase?","How does pH (4.0–10.0) affect the initial rate of breakdown of hydrogen peroxide (mmol dm⁻³ min⁻¹) by potato catalase at 25 °C, investigated with an enzyme simulation?","Does catalase work better in acid or alkali?"],rqA:2,rqWhy:"It names the IV with its range, the DV with units, the enzyme and source, the fixed temperature and the method. The others are too broad, or can be answered with one word.",rqGuide:"Choose <b>amylase</b> (starch → maltose) or <b>catalase</b> (hydrogen peroxide → water + oxygen) and say which in your question.",bgRules:[["active site","You explain the active site.","Explain the role of the active site."],["R-group|ionis|charge|H\\+|hydrogen ion","You link pH to charges on R-groups.","Link pH (H⁺ concentration) to the charges on R-groups in the active site."],["denatur","You explain denaturation.","Explain denaturation at extreme pH."],["optimum","You use the idea of an optimum pH.","Use the idea of an optimum pH."]],hypRules:[["optimum|highest|maximum|peak|near (pH )?7|neutral","You predict where the maximum will be.","Predict where the maximum rate will be."]],mechRules:[["active site","You use the active site.","Explain using the active site."],["R-group|ionis|charge|H\\+","You explain the effect on charges.","Explain how pH changes charges on R-groups."],["enzyme.substrate|E.S|complex|bind","You link to substrate binding.","Link to fewer enzyme–substrate complexes."]],varItems:[["pH of the reaction mixture",0],["Initial rate of reaction (product in the first 60 s)",1],["Temperature (25 °C)",2],["Substrate concentration",2],["Enzyme concentration",2],["Colour of the lab coat",3],["Inhibitor (none)",2]],testMcq:{type:"mcq",k:"testmcq",q:"You compare the mean rate at seven pH values (five repeats each). Which test fits best?",opts:["A t-test between every pair of pH values","One-way ANOVA","Chi-squared test","Spearman rank correlation"],a:1,why:"ANOVA compares the means of three or more independent groups in one test. Many separate t-tests raise the chance of a false positive; Spearman suits a steady (monotonic) trend, but the pH curve rises and then falls."},statsNote:"If the ANOVA is significant, you can use Welch’s t-tests (Statistics lab) to compare the optimum with its neighbours, as in the exemplar.",simGuide:["Open the simulator (button at the top). Choose <b>Catalase (potato)</b> or <b>Salivary amylase</b>. Set temperature 25 °C (or 37 °C for amylase), substrate 20 mmol dm⁻³, enzyme 1.0 and inhibitor none, and check them before every run.","Set the pH, press <b>Run</b>, and read the product concentration at 60 s from the data table. Repeat five times at each pH: the simulator adds a small random error, like a real measurement.","A preliminary run at pH 2 and 12 shows almost no product: test across the measurable range."],ex:{rq:"How does pH (4.0, 5.0, 6.0, 7.0, 8.0, 9.0 and 10.0) affect the initial rate of breakdown of hydrogen peroxide (mmol dm⁻³ min⁻¹) by potato catalase at 25 °C, investigated with a computer simulation of enzyme kinetics?",rqNote:"IV with seven levels, DV with units, enzyme and source, fixed temperature, and the method.",engage:"I became interested after a class practical where potato extract foamed strongly in fresh peroxide but hardly at all when we added vinegar. Because pH inside cells is tightly regulated, I wanted to measure how sensitive this enzyme is to pH.",background:"Enzymes are globular proteins whose active sites have a specific shape and charge distribution. Changing the pH changes the concentration of H⁺ ions, which alters the ionisation of amino-acid R-groups in the active site, so the substrate binds less well; extreme pH breaks the ionic and hydrogen bonds that hold the tertiary structure, denaturing the enzyme (Urry et al., 2020). Catalase works mainly in peroxisomes, close to neutral pH, so I expect an optimum near pH 7 (Allott and Mindorff, 2014).",vars:[["pH of the reaction mixture","Independent","Set with the pH slider to 4.0–10.0, 1.0 apart, to show both sides of the optimum."],["Initial rate (mmol dm⁻³ min⁻¹)","Dependent","Product formed in the first 60 s, read from the data table to 0.01 mmol dm⁻³."],["Temperature","Controlled","Fixed at 25 °C: it changes collision rate and denaturation."],["Substrate concentration","Controlled","Fixed at 20 mmol dm⁻³: more substrate raises the rate until active sites are saturated."],["Enzyme concentration","Controlled","Fixed at 1.0: the number of active sites sets the maximum rate."]],h0:"There is no significant difference in the mean initial rate between the pH values tested.",h1:"The mean initial rate differs significantly between pH values, highest near pH 7 and lower as the pH moves away from 7, because the ionisation of active-site R-groups changes and reduces substrate binding.",method:["Opened the enzyme simulator and selected “Catalase (potato)”.","Set temperature 25 °C, substrate 20 mmol dm⁻³, enzyme 1.0, inhibitor none; checked these before every run.","Set the pH to 4.0, pressed Run and recorded the product at 60 s.","Repeated five times at the same pH (the simulator adds about ±3 % random error).","Repeated for pH 5.0 to 10.0 (35 runs) and exported the table as CSV."],calc:"pH 7.0: mean = (5.47 + 5.66 + 5.61 + 5.68 + 5.55) ÷ 5 = 5.59 mmol dm⁻³ min⁻¹; half range = (5.68 − 5.47) ÷ 2 = 0.105; percentage uncertainty = 0.105 ÷ 5.59 × 100 = 1.9 %.",conclusion:"The mean initial rate rose from 0.63 ± 0.02 mmol dm⁻³ min⁻¹ at pH 4.0 to a maximum of 5.59 ± 0.11 at pH 7.0, then fell to 0.63 ± 0.02 at pH 10.0. One-way ANOVA showed the differences are significant (F(6, 28) = 5818, p < 0.001), so H₀ is rejected. Away from pH 7, R-groups in the active site gain or lose H⁺, changing its charge and shape so fewer enzyme–substrate complexes form. An optimum near neutrality agrees with catalase working in peroxisomes (Allott and Mindorff, 2014).",evals:[["The data come from a model that assumes a symmetrical pH curve with its optimum at 7.0.","Major: the conclusion is about the model, not proven for real potato catalase.","Repeat pH 5, 7 and 9 in the laboratory with potato extract and buffers, measuring O₂ with a gas syringe."],["pH interval of 1.0.","Moderate: the true optimum could lie between pH 6 and 8.","Add pH 6.5 and 7.5 to locate the optimum more precisely."]]}}),h({id:"ia-light-photosynthesis",title:"Light intensity and the rate of photosynthesis",summary:"How does the distance of a lamp (light intensity) affect the rate of photosynthesis of an aquatic plant? Count bubbles with the photosynthesis simulator, then test the relationship.",sim:["/simulations/photosynthesis/","photosynthesis simulator"],minutes:150,iv:"Lamp distance",ivUnit:"cm",dv:"Rate of oxygen production",dvUnit:"bubbles min⁻¹",levels:[10,15,20,30,40,50],test:"spearman",graphTitle:"Effect of lamp distance on the rate of photosynthesis",example:[[45,43,45,46,45],[38,35,39,38,38],[31,30,31,29,30],[19,19,20,21,21],[13,13,14,13,13],[9,10,10,9,9]],rqOpts:["Does light affect photosynthesis?","How does lamp distance (10–50 cm) affect the rate of oxygen production (bubbles min⁻¹) by Cabomba at 25 °C and 1 % hydrogencarbonate, using a photosynthesis simulation?","What is the best light for plants?","How fast do plants photosynthesise?"],rqA:1,rqWhy:"It gives the IV range and units, the DV and how it is counted, the plant, and the fixed temperature and CO₂ supply.",bgRules:[["light.dependent|chlorophyll|photolysis|ATP|NADPH","You explain the light-dependent reactions.","Explain how light drives the light-dependent reactions."],["limiting","You use limiting factors.","Explain limiting factors."],["inverse square|1\\s*/\\s*d|distance","You link distance to intensity.","Link lamp distance to light intensity (inverse square law)."]],hypRules:[["decrease|fall|lower|increase|higher|negative|inverse","You predict the direction.","Predict the direction of the trend."]],mechRules:[["limiting","You use limiting factors.","Explain using limiting factors."],["light.dependent|ATP|NADPH|photolysis|chlorophyll","You use the light-dependent reactions.","Link light intensity to the light-dependent reactions."]],varItems:[["Distance of the lamp from the plant",0],["Number of bubbles per minute",1],["Temperature of the water bath",2],["Hydrogencarbonate concentration (CO₂ supply)",2],["Colour of the light",2],["The day of the week",3]],testMcq:{type:"mcq",k:"testmcq",q:"You want to know whether bubble rate changes steadily as lamp distance increases. Which test fits best?",opts:["Chi-squared test","Spearman rank correlation (or Pearson if the relationship is linear and data normal)","Paired t-test","Mann–Whitney U test"],a:1,why:"Both variables are numerical and you are testing for a relationship, so a correlation fits. Spearman does not need a straight line; the curve here is not linear."},statsNote:"Spearman uses every reading, ranked. A strong negative rₛ with a small p-value means rate falls as distance increases.",simGuide:["Open the simulator. Keep hydrogencarbonate 1 %, water bath 25 °C and white light for every run.","Set the lamp distance, let the plant adjust, press <b>▶ Start counting</b> and record bubbles per minute. Press <b>➕ Record trial</b>. Do five trials at each distance.","Light intensity ∝ 1 ÷ d²: you can add a processed column of 1/d² and plot rate against it as an extension."],ex:{rq:"How does lamp distance (10, 15, 20, 30, 40 and 50 cm) affect the rate of oxygen production (bubbles min⁻¹) by Cabomba at 25 °C and 1 % sodium hydrogencarbonate, investigated with a photosynthesis simulation?",rqNote:"Specific range, a countable DV, and the two other limiting factors fixed.",engage:"On a school trip I noticed pondweed covered in bubbles in a sunny pond but not in a shaded one, and I wanted to measure how strongly light controls photosynthesis.",background:"In the light-dependent reactions, light absorbed by chlorophyll drives photolysis of water, releasing oxygen and making ATP and NADPH for the Calvin cycle (Allott and Mindorff, 2014). Light intensity falls with the square of the distance from a point source, so moving the lamp away reduces the energy reaching the leaves. When light is the limiting factor, the rate should fall as distance increases; at very short distances, CO₂ or temperature may limit the rate instead (Urry et al., 2020).",vars:[["Lamp distance (cm)","Independent","Set with the slider to 10–50 cm."],["Rate of O₂ production (bubbles min⁻¹)","Dependent","Bubbles counted for one minute after a settling time."],["Temperature","Controlled","25 °C water bath: enzymes of the Calvin cycle depend on temperature."],["CO₂ supply","Controlled","1 % hydrogencarbonate, so CO₂ does not limit the rate at long distances."],["Wavelength","Controlled","White light throughout."]],h0:"There is no significant correlation between lamp distance and the rate of oxygen production.",h1:"The rate of oxygen production falls as lamp distance increases (a significant negative correlation), because less light energy reaches the chlorophyll, so fewer ATP and NADPH are made in the light-dependent reactions.",method:["Opened the photosynthesis simulator; set hydrogencarbonate 1 %, 25 °C, white light.","Set the lamp at 10 cm and waited for the bubble rate to settle.","Counted bubbles for 1 minute; recorded the trial.","Took five trials at each distance.","Repeated at 15, 20, 30, 40 and 50 cm."],calc:"20 cm: mean = (31 + 30 + 31 + 29 + 30) ÷ 5 = 30.2 bubbles min⁻¹; half range = (31 − 29) ÷ 2 = 1.0.",conclusion:"The mean rate fell from 44.8 ± 1.5 bubbles min⁻¹ at 10 cm to 9.4 ± 0.5 at 50 cm. Spearman’s rₛ was strongly negative with p < 0.001, so H₀ is rejected. The fall is steepest between 10 and 30 cm, as expected if light intensity falls with 1/d², and the curve flattens at short distances where CO₂ starts to limit the rate (Allott and Mindorff, 2014).",evals:[["Bubble counting assumes all bubbles are the same size and pure oxygen.","Moderate: rate is an index, not a volume of O₂.","Collect gas in a capillary (photosynthometer) and measure its volume."],["The lamp also heats the water at short distances in a real lab.","Moderate in a real lab: temperature would not be controlled.","Put a heat shield (beaker of water) between lamp and plant, and monitor temperature."]]}}),h({id:"ia-osmosis",title:"Sucrose concentration and osmosis in potato tissue",summary:"Find the water potential of potato tissue: how does sucrose concentration affect the percentage change in volume (mass) of potato cells? Uses the osmosis simulator.",sim:["/simulations/osmosis/","osmosis simulator"],minutes:150,iv:"Sucrose concentration",ivUnit:"mol dm⁻³",dv:"Change in volume",dvUnit:"%",levels:[0,.1,.2,.3,.4,.6,.8],calc:2,test:"spearman",line:!1,graphTitle:"Effect of sucrose concentration on the volume change of potato tissue",example:[[13.9,14.1,13.9,14.6,14.2],[8.7,9.1,8.8,8.9,8.1],[3.4,3.2,3.3,3.5,3],[-1.9,-1.3,-2.2,-1.9,-1.4],[-6.7,-7.4,-6.7,-6.6,-6.9],[-22.2,-22.4,-22.9,-22.3,-22],[-34.9,-35.3,-34.8,-34.7,-34.5]],rqOpts:["How does sucrose concentration (0.0–0.8 mol dm⁻³) affect the percentage change in volume of potato tissue after 30 minutes at 20 °C, using an osmosis simulation?","Does sugar make potatoes shrink?","What is osmosis?","How do plant cells take in water?"],rqA:0,rqWhy:"It gives the IV range and units, the DV as a percentage change, the time and temperature, and the method.",bgRules:[["water potential","You use water potential.","Explain with water potential."],["solute potential|pressure potential|turgor","You use solute and pressure potential.","Explain solute potential and pressure potential (turgor)."],["partially permeable|aquaporin|membrane","You describe the membrane.","Mention the partially permeable membrane."],["isotonic|equal","You mention the isotonic point.","Explain the isotonic point (no net movement)."]],hypRules:[["decrease|lose|shrink|negative|gain|increase","You predict the direction.","Predict the direction of volume change."],["isotonic|no change|0 %|zero","You predict the isotonic point.","Predict the concentration where there is no change.","mid"]],mechRules:[["water potential","You explain with water potential.","Explain using water potential gradients."],["osmosis|net movement","You use osmosis.","Use the term osmosis (net movement of water)."]],varItems:[["Concentration of the sucrose solution",0],["Percentage change in volume of the tissue",1],["Temperature",2],["Time in the solution",2],["Membrane permeability",2],["Brand of the potato peeler",3]],testMcq:{type:"mcq",k:"testmcq",q:"Which analysis best finds the water potential of the tissue?",opts:["A t-test between 0.0 and 0.8 mol dm⁻³","Plot % change against concentration, draw a line of best fit and read where it crosses 0 %; use correlation (or regression) for the trend","Chi-squared test","Compare the two largest values"],a:1,why:"The x-intercept (no net change) gives the isotonic concentration, from which you calculate water potential (Ψ = −iCRT). A correlation or regression tests the trend."},statsNote:"Read the isotonic point from your graph where the line crosses 0 %. Convert it to water potential: Ψ = −CRT (C in mol dm⁻³, R = 8.31, T in K, gives kPa).",simGuide:["Open the simulator and choose <b>Plant cell (potato tissue)</b>. Keep permeability 1.0 and temperature 20 °C.","Set the sucrose concentration, run for 30 minutes of model time and read the percentage volume change. Record five trials at each concentration (each run varies slightly as tissue samples would).","In a wet lab you would weigh potato cylinders; the percentage change in mass behaves like the percentage change in volume."],ex:{rq:"How does the concentration of sucrose solution (0.0, 0.1, 0.2, 0.3, 0.4, 0.6 and 0.8 mol dm⁻³) affect the percentage change in volume of potato tissue after 30 minutes at 20 °C, investigated with an osmosis simulation?",rqNote:"Clear range, a percentage DV that allows comparison, fixed time and temperature.",engage:"My grandmother soaks cut vegetables in salty water to keep them crisp, and I wanted to understand when tissue gains or loses water.",background:"Water moves by osmosis from higher to lower water potential across the partially permeable membrane. The water potential of a plant cell is the sum of its solute potential (negative, from dissolved solutes) and pressure potential (turgor from the wall). In a solution with a higher water potential the tissue gains water and swells; in a lower one it loses water and may plasmolyse. At the isotonic point there is no net movement (Allott and Mindorff, 2014).",vars:[["Sucrose concentration (mol dm⁻³)","Independent","Set to 0.0–0.8 with the slider."],["Volume change (%)","Dependent","Read after 30 minutes of model time."],["Temperature","Controlled","20 °C: it affects the rate of water movement."],["Time","Controlled","30 minutes for every run."],["Permeability","Controlled","1.0 (relative)."]],h0:"There is no significant correlation between sucrose concentration and the percentage change in volume.",h1:"The percentage change in volume decreases as sucrose concentration increases, from a gain in dilute solutions to a loss in concentrated ones, because the water potential of the solution falls below that of the cells.",method:["Opened the osmosis simulator and chose plant cell (potato).","Set permeability 1.0, temperature 20 °C.","Set 0.0 mol dm⁻³ sucrose, ran for 30 minutes, recorded the volume change.","Did five runs at each concentration.","Repeated for 0.1 to 0.8 mol dm⁻³."],calc:"0.2 mol dm⁻³: mean = (3.4 + 3.2 + 3.3 + 3.5 + 3.0) ÷ 5 = 3.28 %; half range = (3.5 − 3.0) ÷ 2 = 0.25 %.",conclusion:"The mean volume change fell from +14.1 % in water to −34.8 % at 0.8 mol dm⁻³, a strong negative correlation (Spearman, p < 0.001). The line crosses 0 % at about 0.27 mol dm⁻³, so the tissue’s water potential is about −0.27 × 8.31 × 293 ≈ −660 kPa. Below this concentration the solution has a higher water potential than the cells, so water enters by osmosis.",evals:[["The interval between 0.2 and 0.4 mol dm⁻³ is wide around the isotonic point.","Moderate: the x-intercept is estimated by interpolation.","Add 0.25, 0.30 and 0.35 mol dm⁻³."],["The model uses fixed values for the cell’s solutes.","Major: real potatoes vary with variety and age.","Repeat with real cylinders from several potatoes, measuring mass to 0.01 g."]]}}),h({id:"ia-respiration-temperature",title:"Temperature and the rate of respiration",summary:"How does temperature affect the rate of oxygen uptake by germinating peas? Use the respirometer simulator, then explain the trend with enzymes and Q₁₀.",sim:["/simulations/respiration/","respirometer simulator"],minutes:150,iv:"Temperature",ivUnit:"°C",dv:"Rate of oxygen uptake",dvUnit:"mm³ g⁻¹ min⁻¹",levels:[10,15,20,25,30,35,40],calc:2,test:"anova",graphTitle:"Effect of temperature on the rate of respiration of germinating peas",example:[[.46,.44,.43,.44,.44],[.64,.67,.63,.65,.62],[.89,.93,.93,.88,.9],[1.32,1.3,1.22,1.28,1.22],[1.83,1.78,1.84,1.76,1.78],[2.52,2.52,2.66,2.53,2.42],[1.29,1.28,1.35,1.26,1.3]],rqOpts:["How does heat affect seeds?","How does temperature (10–40 °C) affect the rate of oxygen uptake (mm³ g⁻¹ min⁻¹) by 5 g of germinating peas, measured over 10 minutes with a respirometer simulation?","Do peas breathe faster when warm?","What temperature is best for peas?"],rqA:1,rqWhy:"It names the IV range and units, the DV with units, the organism and mass, the time and the method.",bgRules:[["enzyme","You link respiration to enzymes.","Explain that respiration is controlled by enzymes."],["kinetic|collision","You use kinetic energy and collisions.","Explain the effect of temperature on kinetic energy and collisions."],["denatur","You explain denaturation.","Explain denaturation at high temperatures."],["soda lime|potassium hydroxide|KOH|CO₂ absorb|carbon dioxide","You explain how the respirometer works.","Explain why CO₂ is absorbed in a respirometer."]],hypRules:[["increase|rise|higher|peak|optimum|fall","You predict the trend.","Predict the trend, including what happens above the optimum."]],mechRules:[["enzyme","You use enzymes.","Explain using enzymes of respiration."],["denatur|active site","You explain the fall at 40 °C.","Explain the fall at the highest temperature."]],varItems:[["Temperature of the water bath",0],["Rate of oxygen uptake",1],["Mass of peas",2],["Time of each run",2],["Type and age of seeds",2],["Colour of the water bath",3]],testMcq:{type:"mcq",k:"testmcq",q:"The rate rises to 35 °C and then falls. You compare seven temperatures with five repeats each. Which test fits?",opts:["Spearman rank correlation","One-way ANOVA","Chi-squared test","Paired t-test"],a:1,why:"Spearman needs a steady (monotonic) trend, but this one rises and falls. ANOVA compares the means of all seven groups at once."},statsNote:"You can also calculate Q₁₀ = rate at (T + 10) ÷ rate at T for the rising part (for example 30 °C ÷ 20 °C).",simGuide:["Open the respirometer simulator. Choose <b>Germinating peas</b>, 5 g, and a 10-minute run.","Set the water bath temperature, press <b>▶ Start</b>, and record the rate (it is calculated from the distance moved by the fluid, πr²d, ÷ mass ÷ time). Record five trials at each temperature.","Run a control with glass beads to see why one is needed."],ex:{rq:"How does temperature (10, 15, 20, 25, 30, 35 and 40 °C) affect the rate of oxygen uptake (mm³ g⁻¹ min⁻¹) by 5 g of germinating peas over 10 minutes, measured with a respirometer simulation?",rqNote:"Seven temperatures, a rate with units, and fixed mass and time.",engage:"Farmers near my home wait for the soil to warm before planting maize, and I wanted to see how much temperature speeds up the respiration that powers germination.",background:"Aerobic respiration (C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O) is a series of enzyme-controlled reactions. Raising the temperature increases the kinetic energy of enzyme and substrate molecules, so successful collisions are more frequent; above the optimum, enzymes begin to denature. In a respirometer, CO₂ is absorbed by soda lime, so the fluid moves because of oxygen uptake alone (Allott and Mindorff, 2014).",vars:[["Temperature (°C)","Independent","Water bath set to 10–40 °C."],["Rate of O₂ uptake (mm³ g⁻¹ min⁻¹)","Dependent","Volume of O₂ (πr²d) ÷ mass ÷ time."],["Mass of peas","Controlled","5 g: more seeds use more oxygen."],["Duration","Controlled","10 minutes."],["Seed type","Controlled","Germinating peas of the same age."]],h0:"There is no significant difference in the mean rate of oxygen uptake between the temperatures tested.",h1:"The rate of oxygen uptake increases with temperature up to about 35 °C and then falls, because higher kinetic energy increases enzyme–substrate collisions until enzymes begin to denature.",method:["Opened the respirometer simulator; chose germinating peas, 5 g, 10 minutes.","Set the water bath to 10 °C and ran the respirometer.","Recorded the calculated rate; did five runs.","Repeated at 15–40 °C.","Ran a glass-bead control at 25 °C."],calc:"20 °C: mean = (0.89 + 0.93 + 0.93 + 0.88 + 0.90) ÷ 5 = 0.906 mm³ g⁻¹ min⁻¹; Q₁₀ (20 → 30 °C) = 1.80 ÷ 0.906 ≈ 2.0.",conclusion:"The mean rate rose from 0.44 mm³ g⁻¹ min⁻¹ at 10 °C to a maximum of 2.53 at 35 °C, then fell to 1.30 at 40 °C. ANOVA showed significant differences (p < 0.001). Q₁₀ between 20 and 30 °C was about 2.0, typical of enzyme-controlled reactions; the fall at 40 °C suggests denaturation of respiratory enzymes.",evals:[["The model uses a fixed Q₁₀ and a fixed denaturation temperature.","Major: real seeds may differ.","Repeat 20, 30 and 40 °C with real peas in a respirometer."],["The 5 °C interval misses the exact optimum between 30 and 40 °C.","Moderate.","Add 32, 34, 36 and 38 °C."]]}}),h({id:"ia-temperature-enzyme",title:"Temperature and amylase activity",summary:"How does temperature affect the initial rate of starch breakdown by amylase? Uses the enzyme simulator; a good second enzyme investigation after pH.",sim:["/simulations/enzyme/","enzyme activity simulator"],minutes:150,iv:"Temperature",ivUnit:"°C",dv:"Initial rate",dvUnit:"mmol dm⁻³ min⁻¹",levels:[10,20,30,40,50,60],calc:3,test:"anova",graphTitle:"Effect of temperature on the initial rate of amylase activity",example:[[1.26,1.27,1.22,1.28,1.22],[2.52,2.56,2.61,2.53,2.62],[4.88,5.05,4.93,4.94,4.81],[8.26,8.45,8.51,8.49,8.59],[2.9,2.95,2.85,2.8,2.84],[.11,.11,.11,.11,.11]],rqOpts:["How does temperature (10–60 °C) affect the initial rate of maltose production (mmol dm⁻³ min⁻¹) by salivary amylase at pH 6.8, using an enzyme simulation?","Is amylase faster when hot?","What happens to enzymes at high temperature?","How do enzymes work?"],rqA:0,rqWhy:"IV range and units, DV with units, enzyme, fixed pH and method.",bgRules:[["kinetic|collision","You use kinetic energy and collisions.","Explain the effect of temperature on collisions."],["active site","You use the active site.","Explain the role of the active site."],["denatur","You explain denaturation.","Explain denaturation above the optimum."]],hypRules:[["optimum|peak|maximum|37|40","You predict an optimum.","Predict where the optimum will be."]],mechRules:[["kinetic|collision","You explain the rise.","Explain the rise with collisions."],["denatur|hydrogen bond|tertiary","You explain the fall.","Explain the fall with denaturation."]],varItems:[["Temperature",0],["Initial rate of maltose production",1],["pH (6.8)",2],["Starch concentration",2],["Amylase concentration",2],["Size of the computer screen",3]],testMcq:{type:"mcq",k:"testmcq",q:"Which test compares the mean rate at six temperatures?",opts:["Chi-squared","One-way ANOVA","Spearman rank correlation","No test is needed"],a:1,why:"Six independent groups of continuous data: ANOVA. Spearman does not fit a rise-then-fall curve."},statsNote:"At 60 °C every trial gives the same value: the enzyme is fully denatured. That is still a valid group.",simGuide:["Open the simulator and choose <b>Salivary amylase</b>. Set pH 6.8, substrate 20 mmol dm⁻³, enzyme 1.0, inhibitor none.","Set the temperature, press <b>Run</b>, and read the product at 60 s. Five trials at each temperature."],ex:{rq:"How does temperature (10, 20, 30, 40, 50 and 60 °C) affect the initial rate of maltose production (mmol dm⁻³ min⁻¹) by salivary amylase at pH 6.8, investigated with an enzyme simulation?",rqNote:"Six temperatures, a rate with units, the fixed pH.",engage:"I wondered why bread tastes sweeter the longer I chew it, and whether hot drinks would affect the amylase in my saliva.",background:"Amylase hydrolyses starch to maltose. Raising the temperature increases the kinetic energy of molecules, so enzyme–substrate collisions are more frequent; above the optimum, vibrations break hydrogen bonds in the tertiary structure, the active site changes shape and the enzyme denatures (Urry et al., 2020). Human amylase has an optimum near body temperature (Allott and Mindorff, 2014).",vars:[["Temperature (°C)","Independent","10–60 °C, 10 °C apart."],["Initial rate (mmol dm⁻³ min⁻¹)","Dependent","Maltose at 60 s."],["pH","Controlled","6.8 (salivary pH)."],["Substrate concentration","Controlled","20 mmol dm⁻³."],["Enzyme concentration","Controlled","1.0."]],h0:"There is no significant difference in the mean initial rate between temperatures.",h1:"The rate rises to an optimum near 40 °C and falls steeply above it, because collisions increase with kinetic energy until the enzyme denatures.",method:["Opened the simulator; chose salivary amylase; set pH 6.8, substrate 20, enzyme 1.0.","Set 10 °C, ran, recorded the product at 60 s.","Five runs at each temperature from 10 to 60 °C."],calc:"40 °C: mean = (8.26 + 8.45 + 8.51 + 8.49 + 8.59) ÷ 5 = 8.46 mmol dm⁻³ min⁻¹.",conclusion:"The mean rate rose from 1.25 at 10 °C to 8.46 mmol dm⁻³ min⁻¹ at 40 °C, then fell to 2.87 at 50 °C and 0.11 at 60 °C (ANOVA, p < 0.001). The steep fall above 40 °C fits denaturation; the optimum in this range is 40 °C to within ± 10 °C.",evals:[["10 °C interval.","Moderate: the optimum could be anywhere from 30 to 50 °C.","Add 35, 40, 45 °C and test 1 °C steps near the peak."],["Simulated data.","Major.","Repeat with real amylase and starch, using iodine and a colorimeter."]]}}),h({id:"ia-transect",title:"A belt transect: plant cover from woodland to meadow",summary:"How does the percentage cover of meadow grass change with distance across a woodland edge? Walk the transect simulator, then test the correlation and link it to light.",sim:["/simulations/transect/","transect simulator"],minutes:150,iv:"Distance along the transect",ivUnit:"m",dv:"Percentage cover of meadow grass",dvUnit:"%",levels:[0,4,8,12,16,20,24,28,32,36,40],calc:5,trials:3,test:"spearman",graphTitle:"Cover of meadow grass along a woodland-to-meadow transect",example:[[1,3,1],[0,0,0],[1,0,0],[1,0,0],[35,36,33],[86,96,90],[85,93,92],[81,84,85],[77,94,81],[74,88,82],[76,77,76]],rqOpts:["Where does grass grow?","How does distance (0–40 m) along a belt transect from inside a woodland into a meadow affect the percentage cover of meadow grass, measured in 0.25 m² quadrats every 4 m in a transect simulation?","Do trees affect plants?","How many plants are in a meadow?"],rqA:1,rqWhy:"It names the gradient, the range, the species, how cover is measured and the sampling interval.",bgRules:[["tolerance|optimum","You use range of tolerance.","Explain range of tolerance."],["light|abiotic","You name the abiotic factor.","Name the abiotic factor that changes along the transect."],["quadrat|percentage cover|transect","You explain the sampling method.","Explain the transect and quadrat method."]],hypRules:[["increase|higher|more|positive","You predict the direction.","Predict how cover changes from woodland to meadow."]],mechRules:[["light","You link cover to light.","Link the pattern to light intensity."],["tolerance|shade|compet","You explain with tolerance or competition.","Explain using range of tolerance or competition."]],varItems:[["Distance along the transect",0],["Percentage cover of meadow grass",1],["Quadrat size",2],["Interval between stations",2],["Same person estimating cover",2],["The colour of the measuring tape",3]],testMcq:{type:"mcq",k:"testmcq",q:"You want to test whether cover changes with distance. The data are percentages and not normally distributed. Which test?",opts:["Spearman rank correlation","Pearson correlation","ANOVA","Paired t-test"],a:0,why:"Spearman tests a monotonic relationship and does not assume normal data. Percentage cover with many zeros is not normal."},statsNote:"A field correlation shows association, not cause: light, moisture and competition all change along the transect.",simGuide:["Open the transect simulator. Choose <b>Meadow grass</b> and a 2 m or 4 m interval.","Press <b>▶ Walk the transect</b> and record cover at the stations in the table (0, 4, 8 … 40 m). Walk it three times for three quadrats per station.","Also record light at each station: you can test cover against light as an extension."],ex:{rq:"How does distance (0–40 m) along a belt transect from inside a woodland into an open meadow affect the percentage cover of meadow grass, measured in 0.25 m² quadrats every 4 m (three quadrats per station), using a transect simulation?",rqNote:"The gradient, species, measure and sampling design are all clear.",engage:"Walking from the forest into the school field, the ground changes from bare leaf litter to thick grass within a few metres, and I wanted to measure how sharp this change is.",background:"Each species survives within a range of tolerance of each abiotic factor, with an optimum where it grows best. Under a canopy, light intensity is low; meadow grasses are light-demanding and are outcompeted or cannot photosynthesise enough in shade. A belt transect samples along an environmental gradient with quadrats at fixed stations, and percentage cover estimates abundance (Allott and Mindorff, 2014).",vars:[["Distance (m)","Independent","Stations every 4 m from 0 to 40 m."],["Percentage cover of meadow grass","Dependent","Estimated in a 0.25 m² gridded quadrat."],["Quadrat size","Controlled","0.25 m² for every sample."],["Observer","Controlled","The same person estimated cover each time."]],h0:"There is no significant correlation between distance along the transect and the cover of meadow grass.",h1:"Cover of meadow grass increases with distance into the meadow, because light intensity rises outside the canopy and grass is light-demanding.",method:["Opened the transect simulator; chose meadow grass and a 4 m interval.","Walked the transect and recorded cover at each station.","Repeated the walk three times (three quadrats per station).","Recorded light intensity at each station."],calc:"20 m: mean = (86 + 96 + 90) ÷ 3 = 90.7 %.",conclusion:"Cover was close to 0 % from 0 to 12 m (under the canopy), rose sharply at 16 m (34.7 %) and stayed between 76 % and 91 % from 20 to 40 m. Spearman’s rₛ was strongly positive (p < 0.001). The sharp rise at the woodland edge matches the sharp rise in light intensity, consistent with grass being light-demanding.",evals:[["Cover estimates are subjective.","Moderate.","Use a point frame or a 100-square grid and count squares."],["Correlation does not show which factor causes the change.","Major for explaining the pattern.","Measure light and soil moisture at each station and test each against cover."]]}});function d(e){var t=e.ex,o=[];o.push({title:"Is this the right subject for your essay?",guide:e.subjectGuide,tasks:[e.fitMcq,{type:"text",k:"why",label:"Why "+e.subject+"? What draws you to research in this subject?",min:40,rules:[w],map:"ee_subject.why"}]}),o.push({title:"From topic to focus",guide:["Start with a topic you care about, then narrow it: one organism or system, one variable or relationship, one context. A good EE topic can be researched in about 40 hours and answered in 4,000 words."].concat(e.topicGuide||[]),tasks:[{type:"classify",k:"topics",q:"Sort these ideas for a "+e.subject+" extended essay.",cats:["Suitable and focused","Too broad","Belongs mainly to another subject"],items:e.topics,why:"Correct. A suitable topic is focused and is clearly answered with the methods of this subject.",hint:"Ask: can it be answered in 4,000 words? Is the method a "+e.subject+" method?"},{type:"text",k:"idea",label:"Your topic idea, narrowed to one focus",min:20,map:"ee_topic.idea"},{type:"text",k:"tw",label:"Why it is worth investigating (a gap, a local problem, a question in the literature)",min:30,rules:[f],map:"ee_topic.why"}]}),o.push({title:"Research question",guide:["An EE research question is clear, focused and arguable: it allows analysis and evaluation, not just description. In the sciences it usually names the variables, organism or system, and conditions; “To what extent…” or “How does…” questions work well when they lead to a reasoned argument."],example:{title:"Exemplar research question",text:t.rq,note:t.rqNote},tasks:[{type:"rq",kind:"ee",k:"rq",label:"Your research question",map:"ee_rq.text"},{type:"text",k:"rqr",label:"How you narrowed it (what you left out, and why)",min:25,map:"ee_rq.reasoning"}]}),o.push({title:"Methodology",guide:e.methodGuide,example:{title:"Exemplar methodology (extract)",text:t.method,note:t.methodNote},tasks:[{type:"mcq",k:"mmcq",q:e.methodMcq.q,opts:e.methodMcq.opts,a:e.methodMcq.a,why:e.methodMcq.why},{type:"text",k:"design",label:"Your research design: approach, variables, data you will collect",min:80,tall:!0,rules:e.methodRules.concat([v]),map:"ee_method.design"},{type:"text",k:"ethics",label:"Safety, ethics and environment",min:25,rules:e.ethicsRules,map:"ee_method.ethics"}]}),e.data&&o.push({title:"Pilot study with the simulator",guide:e.data.guide,tasks:[{type:"data",k:"pilot",label:"Pilot data",tip:e.data.tip||"A pilot tests your method and range before the real data collection. Practise with the exemplar data if you wish.",iv:e.data.iv,ivUnit:e.data.ivUnit,dv:e.data.dv,dvUnit:e.data.dvUnit,levels:e.data.levels,trials:e.data.trials||3,example:e.data.example},{type:"stats",from:"pilot",test:e.data.test,label:"A first look at the statistics"},{type:"graph",from:"pilot",label:"Pilot graph",line:e.data.line},{type:"text",k:"pilotlearn",label:"What did the pilot teach you? (range, interval, repeats, method changes)",min:30}]}),o.push({title:"Sources and background knowledge",guide:["Use academic sources: textbooks for the theory, research articles and reviews for current knowledge and comparison values, and reputable databases. Evaluate each source (author, publication, date, method, bias). Record full references as you go and cite in the text."].concat(e.sourceGuide||[]),tasks:[{type:"mcq",k:"smcq",q:"Which source is the strongest evidence for the background of a "+e.subject+" EE?",opts:e.sourceOpts,a:e.sourceA,why:"A peer-reviewed research article or review written by specialists, with methods and data, is the strongest academic evidence. Use websites and videos only to find your way in, then go to the original research."},{type:"text",k:"sources",label:"Your first sources (full references) and what each one adds",min:40,rules:[u],map:"ee_proposal.sources"}]}),o.push({title:"Writing the essay",guide:["Sections usually include: introduction (question, context, why it matters), background, methodology, results and analysis, discussion and evaluation, conclusion, references. Analyse as you go: every table or graph is followed by what it shows and how it answers the question.","Keep a clear <b>line of argument</b>: each section moves the answer forward. Discuss limitations of the method and of the sources, and how they affect the strength of your conclusion."],example:{title:"Exemplar discussion (extract)",text:t.discussion,note:"It interprets the data, links to theory and published work, and judges how far the conclusion can be trusted."},tasks:[{type:"text",k:"intro",label:"Draft your introduction",min:80,tall:!0,rules:[["\\?","It states the research question.","State the research question in the introduction."],[f[0],"You explain why it matters.","Explain why the question is worth answering."]],map:"ee_write:Introduction"},{type:"text",k:"disc",label:"Draft a paragraph of analysis and discussion (from your pilot or expected results)",min:80,tall:!0,rules:[p,u,["however|although|limitation|uncertain|suggest|may|likely","You judge the strength of the evidence.","Judge how strong the evidence is (however, this suggests, a limitation is…)."]],map:"ee_write:Analysis and discussion"}]}),o.push({title:"Assessment criteria and reflection",guide:["The essay is marked on A Framework (research question, methods, structure), B Knowledge and understanding, C Analysis and line of argument, D Discussion and evaluation, and E Reflection (from your Reflections on planning and progress form, RPF, 500 words). Write the RPF yourself, in your own voice: it is not shared with the AI mentor."],tasks:[{type:"classify",k:"crit",q:"Which criterion rewards each of these?",cats:["A Framework","B Knowledge and understanding","C Analysis and line of argument","D Discussion and evaluation","E Reflection"],items:[["A focused research question and a suitable, explained method",0],["Accurate use of "+e.subject+" terminology and relevant sources",1],["Interpreting data and building a coherent argument towards the answer",2],["Judging the strengths and limitations of the evidence and the conclusion",3],["Showing how your thinking and approach changed during the process",4],["Headings, referencing and presentation that help the reader",0]],why:"Correct. Use these as a checklist when you review each section."},{type:"text",k:"reflect",label:"Notes for your first reflection session (what you have decided, what worries you, what you will do next)",min:30,rules:[w]}]}),g.push({id:e.id,group:"EE",subject:e.subject,target:"ee",title:e.title,summary:e.summary,sim:e.sim,download:e.download,minutes:e.minutes||150,sections:o})}var A=[["safe|hazard|risk","You consider safety.","Consider safety."],["ethic|consent|animal|organism|confidential","You consider ethics.","Consider ethics."],["environment|waste|dispos","You consider the environment.","Consider the environment."]],c=function(e){return["A blog post summarising the topic",e,"A popular science video","A student revision website"]};d({id:"ee-biology",subject:"Biology",title:"Extended essay in Biology: guided worksheet",summary:"From topic to research question, method, sources and writing, for a Biology EE. Example: temperature and photosynthesis in an aquatic plant, with a pilot study in the photosynthesis simulator.",sim:["/simulations/photosynthesis/","photosynthesis simulator"],download:"ee-exemplar-biology.docx",subjectGuide:["A Biology EE investigates a biological question using biological methods and theory: experiments in the lab or field, analysis of databases (for example gene sequences or ecological surveys), or simulations, supported by literature. The essay must be clearly about living organisms or biological processes.","Avoid questions that are mainly chemistry (for example vitamin C content by titration alone) or mainly medicine or psychology without a biological investigation. Experiments on vertebrates or that cause harm are not allowed; follow the IB animal experimentation policy."],fitMcq:{type:"mcq",k:"fit",q:"Which question is best suited to a Biology EE?",opts:["How does the concentration of vitamin C in orange juice change with storage time?","To what extent does temperature (5–45 °C) affect the rate of photosynthesis of Cabomba caroliniana, and how far does an enzyme-kinetics model explain the trend?","Which diet is best for weight loss?","How has COVID-19 affected the economy?"],a:1,why:"It investigates a biological process in a named organism and allows analysis and evaluation. Vitamin C by titration is mainly chemistry; the others are too broad or not biology."},topics:[["The effect of light colour on the growth of duckweed (Lemna minor)",0],["Climate change and ecosystems",1],["The vitamin C content of fruit juices by titration",2],["Antibacterial effect of garlic extract on E. coli (school-safe strain) at different concentrations",0],["Genetics",1],["The economics of tea farming",2]],rq:null,methodGuide:["Choose a method that can answer your question: a controlled experiment (with a sufficient range, number of levels and repeats), a field study (sampling design), or analysis of secondary data. Explain why your method suits the question and how you made it valid and reliable.","A simulation can support your essay, but examiners expect you to discuss the model’s assumptions. Strong essays often combine a lab or field experiment with literature values."],methodMcq:{q:"You use the photosynthesis simulator for some of your data. What must the essay include?",opts:["Nothing extra: simulated data are the same as real data.","How the data were generated, the model’s assumptions and how they limit the conclusion.","Only screenshots of the simulator.","A statement that the data are real."],a:1,why:"Simulated and database data are allowed, but you must explain how they were produced and evaluate the limits of the model."},methodRules:[["independent|IV|variable","You name the variables.","Name the independent and dependent variables."],["control|constant|fixed","You control other variables.","Say which variables you control and how."]],ethicsRules:A,sourceOpts:c("A peer-reviewed article on temperature and photosynthesis in aquatic plants (e.g. in Aquatic Botany)"),sourceA:1,data:{guide:["Use the photosynthesis simulator at 20 cm, 1 % hydrogencarbonate and white light. Change the water-bath temperature and record bubbles per minute, three to five trials each."],iv:"Temperature",ivUnit:"°C",dv:"Rate",dvUnit:"bubbles min⁻¹",levels:[5,15,25,30,35,45],trials:5,test:"anova",example:[[1,1,1,1,1],[9,9,9,9,9],[31,30,30,30,29],[35,34,34,34,35],[21,21,21,22,21],[0,0,0,0,0]]},ex:{rq:"To what extent does temperature (5–45 °C) affect the rate of oxygen production by Cabomba caroliniana, and how well does a model of enzyme-controlled photosynthesis explain the results?",rqNote:"Focused (one organism, one variable, a range), and “to what extent… how well” invites evaluation, not just a result.",method:"Rates were measured by counting bubbles for one minute at seven temperatures with five repeats, at constant light (20 cm) and CO₂ (1 % NaHCO₃). The pilot was run in the BioScience Vista simulator to choose the range; the main data were then collected with real Cabomba in a water bath, temperature checked with a digital thermometer (± 0.1 °C). Simulated and real results were compared.",methodNote:"The method is justified, combines a model and real data, and states precision.",discussion:"Real rates rose from 2 bubbles min⁻¹ at 5 °C to a peak of 31 at 30 °C, a similar shape to the model, but the real peak was lower and fell more slowly above 35 °C. This suggests that enzymes of the Calvin cycle in Cabomba may be more heat-tolerant than the model assumes, a pattern of temperature acclimation described for many C₃ plants (Yamori, Hikosaka and Way, 2014). However, bubble counts do not measure volume, so the difference in magnitude may partly reflect bubble size."}}),d({id:"ee-chemistry",subject:"Chemistry",title:"Extended essay in Chemistry: guided worksheet",summary:"A Chemistry EE from question to writing. Example: the concentration of ethanoic acid and its pH, compared with theory, with a pilot in the titration simulator.",sim:["/simulations/titration/","titration simulator"],download:"ee-exemplar-chemistry.docx",subjectGuide:["A Chemistry EE investigates a chemical question using chemical principles and methods: quantitative experiments (titration, colorimetry, calorimetry, kinetics), analysis of data from databases, or modelling, linked to chemical theory.","The chemistry must be central: a biology question that only uses a chemical test is better as a Biology EE. Plan for precise, quantitative data and full uncertainty analysis."],fitMcq:{type:"mcq",k:"fit",q:"Which question is best suited to a Chemistry EE?",opts:["How does the concentration of ethanoic acid (0.01–1.0 mol dm⁻³) affect its pH, and how closely do measured values agree with pH = ½(pKa − log c)?","Which fruit is healthiest?","How do plants respond to acid rain in my garden?","What is the history of the periodic table?"],a:0,why:"It is quantitative, uses chemical theory and allows comparison of data with a model. The others are too broad, mainly biology, or historical."},topics:[["Effect of temperature on the rate of decomposition of hydrogen peroxide with a manganese(IV) oxide catalyst",0],["Pollution",1],["The effect of fertiliser on bean plant growth",2],["Determination of the enthalpy of combustion of a series of alcohols",0],["Acids and bases",1],["The psychology of taste",2]],methodGuide:["Choose a quantitative method, state concentrations, volumes and apparatus with their uncertainties, and propagate uncertainties into your final values. Compare results with theory or literature values (percentage error) and discuss random and systematic errors.","Simulations and databases can be used, but say how data were obtained and test the key results in the laboratory where possible."],methodMcq:{q:"Your measured pH values are all about 0.1 higher than the theoretical values. What does this most likely show?",opts:["A random error","A systematic error, such as a pH meter calibration offset","That the theory is wrong","That more repeats are needed"],a:1,why:"A consistent shift in one direction is a systematic error. Calibrate the pH meter with buffers at two pH values and check."},methodRules:[["concentration|mol|volume|cm³|dm³","You state quantities.","State concentrations and volumes."],["uncertaint|±","You plan uncertainty analysis.","Plan how you will record and propagate uncertainties."]],ethicsRules:[["safe|hazard|corrosive|irritant|goggle","You consider safety.","Consider hazards (corrosive, irritant) and protection."],["dispos|waste|environment|neutrali","You consider waste and the environment.","Plan disposal (neutralise, dilute, minimise)."]],sourceOpts:c("A data book or peer-reviewed article giving the pKa of ethanoic acid and its temperature dependence"),sourceA:1,data:{guide:["Open the titration simulator. Choose ethanoic acid, set its concentration, and read the initial pH before adding base. Three readings each (the simulator gives exact values; in the lab a pH meter reads ± 0.01)."],iv:"Ethanoic acid concentration",ivUnit:"mol dm⁻³",dv:"Initial pH",dvUnit:"",levels:[.01,.05,.1,.25,.5,1],trials:3,test:"spearman",example:[[3.38,3.37,3.37],[3.04,3.03,3.05],[2.89,2.9,2.89],[2.69,2.68,2.69],[2.55,2.52,2.55],[2.38,2.38,2.37]],tip:"Practise processing: plot pH against log₁₀(concentration) for a straight line with gradient −0.5."},ex:{rq:"How does the concentration of ethanoic acid (0.01–1.00 mol dm⁻³) affect its pH at 25 °C, and to what extent do measured values agree with the weak-acid approximation pH = ½(pKa − log₁₀ c)?",rqNote:"Quantitative, theory-linked, and “to what extent” invites evaluation of the approximation.",method:"Six solutions were made by serial dilution of 1.00 mol dm⁻³ ethanoic acid with volumetric flasks (± 0.20 cm³) and pipettes (± 0.06 cm³). The pH meter was calibrated at pH 4.00 and 7.00 and each solution measured three times at 25.0 ± 0.5 °C. A pilot in the titration simulator gave the expected range.",methodNote:"Apparatus uncertainties, calibration and temperature control are stated.",discussion:"A plot of pH against log₁₀ c is linear with a gradient of −0.505 ± 0.002, close to the theoretical −0.500, so the approximation describes the data well across this range. At 0.01 mol dm⁻³ the measured pH (3.39) is slightly above the prediction, which may reflect greater dissociation in dilute solution, where the assumption that [HA] ≈ c is least valid (Atkins and de Paula, 2014)."}}),d({id:"ee-physics",subject:"Physics",title:"Extended essay in Physics: guided worksheet",summary:"A Physics EE from question to writing. Example: how the temperature of a squash ball affects its coefficient of restitution. The example data are illustrative (teacher-created); collect your own in the lab.",download:"ee-exemplar-physics.docx",subjectGuide:["A Physics EE investigates a physical question with physics theory and quantitative methods: an experiment, analysis of data (for example from a database or video analysis), or a simulation or computational model. Derive or explain the relationship you expect, then test it.","Questions that are mainly engineering design or that only describe a technology are weak. Aim for a clear relationship between measurable quantities and a careful uncertainty analysis."],fitMcq:{type:"mcq",k:"fit",q:"Which question suits a Physics EE best?",opts:["How do smartphones work?","How does the temperature of a squash ball (10–60 °C) affect its coefficient of restitution when dropped from 1.00 m onto concrete?","Who was the greatest physicist?","How does exercise affect heart rate?"],a:1,why:"It relates two measurable quantities and can be explained with energy and the properties of rubber. The others are descriptive, historical or biology."},topics:[["Effect of string length on the period of a pendulum at large amplitudes",0],["Space",1],["Effect of caffeine on reaction time",2],["Damping of a mass-spring oscillator in liquids of different viscosity",0],["Electricity",1],["The ethics of nuclear power",2]],methodGuide:["State what you measure, with what instrument and precision; plan enough points across a wide range; and show how you will linearise the relationship for a graph. Analyse gradients with uncertainties (maximum and minimum lines).","Video analysis (e.g. Tracker) and data loggers improve precision. Compare with theory and literature."],methodMcq:{q:"Which is the best way to find the coefficient of restitution e from drop and bounce heights?",opts:["e = h₂ ÷ h₁","e = √(h₂ ÷ h₁), with heights read from slow-motion video against a metre rule","e = h₁ − h₂","Estimate it by eye"],a:1,why:"e is the ratio of speeds; with v = √(2gh), e = √(h₂/h₁). Video analysis reduces parallax and timing errors."},methodRules:[["measur|instrument|ruler|video|logger|sensor","You say how you measure.","Say what instrument you use and its precision."],["uncertaint|±|gradient","You plan uncertainty analysis.","Plan uncertainties and how you will analyse gradients."]],ethicsRules:[["safe|hazard|risk|hot|burn","You consider safety.","Consider hazards (hot water, falling objects)."],["environment|waste|energy","You consider the environment.","Consider energy use and waste."]],sourceOpts:c("A peer-reviewed paper on the temperature dependence of rubber elasticity or ball rebound"),sourceA:1,data:{guide:["There is no simulator for this one: enter your own lab data. The exemplar data are illustrative (made up to show the method), so do not use them in your essay."],iv:"Ball temperature",ivUnit:"°C",dv:"Coefficient of restitution",dvUnit:"",levels:[10,20,30,40,50,60],trials:3,test:"spearman",example:[[.24,.25,.24],[.29,.28,.3],[.34,.35,.33],[.39,.4,.39],[.43,.42,.44],[.46,.45,.46]],tip:"Illustrative example data: use them only to practise. Your essay must use data you collect."},ex:{rq:"How does the temperature of a squash ball (10–60 °C) affect its coefficient of restitution when dropped from 1.00 m onto a concrete floor?",rqNote:"Two measurable quantities, a range and fixed conditions.",method:"Balls were held in a water bath for 10 minutes, dried and dropped within 5 s from 1.000 ± 0.002 m. Each bounce was filmed at 240 frames per second beside a metre rule and the rebound height measured in Tracker (± 0.005 m). Three drops at each of six temperatures.",methodNote:"Precise, repeatable and states uncertainties.",discussion:"e rose from 0.24 at 10 °C to 0.46 at 60 °C, a near-linear increase. Warmer rubber is more elastic and the gas pressure inside the ball is higher, so less energy is lost as heat during the collision. The rate of increase falls above 50 °C, which may reflect cooling of the ball during the 5 s before the drop, a systematic error that would be largest at high temperatures (illustrative example)."}}),d({id:"ee-ess",subject:"Environmental systems and societies",title:"Extended essay in ESS: guided worksheet",summary:"An ESS EE links an environmental system with a human or societal dimension. Example: distance from an ecotourism boardwalk and mangrove seedling density at Mida Creek, Kenya. Practise sampling with the quadrat simulator.",sim:["/simulations/sampling/","sampling simulator"],download:"ee-exemplar-ess.docx",subjectGuide:["An ESS EE must look at the <b>interaction</b> between an environmental system and a societal system (people, management, values, economics). A purely ecological question belongs in Biology; a purely social one in Geography or another subject.","Use a systems approach: identify inputs, outputs, flows and feedback. Fieldwork and surveys are common; secondary data from reliable databases can be used. Consider different environmental value systems when you discuss solutions."],fitMcq:{type:"mcq",k:"fit",q:"Which question suits an ESS EE?",opts:["How does light intensity affect the growth of mangrove seedlings in a greenhouse?","To what extent does distance from the ecotourism boardwalk at Mida Creek affect the density of mangrove seedlings, and what does this suggest for managing visitor access?","What are mangroves?","How many tourists visit Kenya each year?"],a:1,why:"It combines an environmental system (mangrove regeneration) with a societal one (ecotourism management). The first is Biology; the others are descriptive."},topics:[["Effect of informal waste dumping on stream invertebrate diversity and how residents view the problem",0],["Global warming",1],["The rate of photosynthesis of mangrove leaves at different temperatures",2],["Attitudes to plastic bag bans and plastic litter on two beaches",0],["Deforestation in the world",1],["The history of national parks in Kenya",2]],methodGuide:["Combine methods: ecological sampling (quadrats, transects, indices such as Simpson’s) and a social method (questionnaire, interview, policy analysis). Explain your sampling strategy (random, systematic, stratified) and sample size, and how you avoided bias.","Surveys need informed consent, anonymity and the right to withdraw; fieldwork must not damage the habitat."],methodMcq:{q:"You want to compare seedling density near and far from a boardwalk without bias. Which sampling plan is best?",opts:["Place quadrats where seedlings look interesting.","Systematic transects at right angles to the boardwalk, with quadrats every 5 m, repeated at several randomly chosen points along it.","One quadrat near and one far.","Count only on the boardwalk."],a:1,why:"Systematic sampling along the gradient, replicated at random starting points, covers the gradient and avoids choosing sites by eye."},methodRules:[["quadrat|transect|sampl|survey|questionnaire|interview","You name your methods.","Name your ecological and social methods."],["random|systematic|stratified|sample size","You explain the sampling strategy.","Explain your sampling strategy and sample size."]],ethicsRules:[["consent|anonym|withdraw|confidential","You consider ethics for surveys.","Plan informed consent and anonymity for participants."],["trampl|damage|disturb|habitat|permission","You consider the habitat.","Avoid damaging the habitat; get permission for fieldwork."],["safe|tide|risk","You consider safety.","Consider safety (tides, mud, heat)."]],sourceOpts:c("A peer-reviewed study of mangrove regeneration and human disturbance in East Africa"),sourceA:1,data:{guide:["Practise quadrat sampling in the simulator first. For the essay, enter your field data: seedling counts per 1 m² quadrat at each distance from the boardwalk. The example values are illustrative."],iv:"Distance from the boardwalk",ivUnit:"m",dv:"Seedling density",dvUnit:"seedlings m⁻²",levels:[0,5,10,15,20,25],trials:3,test:"spearman",example:[[2,1,3],[5,4,6],[9,8,11],[12,14,13],[15,13,16],[16,15,17]],tip:"Illustrative example data: practise with them, then use your own field data."},ex:{rq:"To what extent does distance from the ecotourism boardwalk at Mida Creek, Kenya, affect the density of mangrove (Rhizophora mucronata) seedlings, and what does this suggest about managing visitor access?",rqNote:"A named place, species and gradient, plus a management dimension that links the environmental and societal systems.",method:"Six systematic transects ran at right angles to the boardwalk; seedlings were counted in 1 m² quadrats every 5 m to 25 m. Twenty visitors and five guides completed an anonymous questionnaire about walking off the boardwalk. Consent was obtained and quadrats were placed from the edge to avoid trampling.",methodNote:"Ecological and social data, a justified sampling design, and ethical care.",discussion:"Seedling density increased from about 2 m⁻² beside the boardwalk to about 16 m⁻² at 25 m (Spearman, p < 0.001), and 40 % of visitors said they had stepped off the boardwalk to take photographs. This suggests that trampling near the boardwalk limits regeneration, although sediment and light also change with distance. A railing and guide briefing would reflect an ecocentric value system while keeping the economic benefits of ecotourism (illustrative example)."}}),d({id:"ee-sehs",subject:"Sports, exercise and health science",title:"Extended essay in SEHS: guided worksheet",summary:"An SEHS EE investigates sport, exercise or health using physiology, biomechanics or psychology of sport. Example: training status and heart-rate recovery after exercise, with a pilot in the pulse simulator.",sim:["/simulations/pulse/","pulse simulator"],download:"ee-exemplar-sehs.docx",subjectGuide:["An SEHS EE applies the science of sport, exercise and health to a focused question: physiology (heart rate, VO₂, lactate), biomechanics (forces, angles, technique), nutrition, or the psychology of performance. Data usually come from human participants or published databases.","Work with human participants needs informed (and, for under-18s, parental) consent, the right to withdraw, screening (e.g. PAR-Q), safe intensity and anonymity. Never use maximal tests without supervision."],fitMcq:{type:"mcq",k:"fit",q:"Which question suits an SEHS EE?",opts:["How does the heart work?","To what extent does training status (trained vs untrained 16–18-year-olds) affect heart-rate recovery in the five minutes after a 2-minute step test?","Which football team is the best?","How does temperature affect enzymes in yeast?"],a:1,why:"It is a focused exercise-physiology question with measurable data from consenting participants. The others are descriptive, not science, or Biology."},topics:[["Effect of a dynamic warm-up on 20 m sprint time in school athletes",0],["Fitness",1],["The effect of glucose on yeast respiration",2],["Knee angle at take-off and standing long jump distance",0],["Sport in society",1],["The economics of the Olympics",2]],methodGuide:["Define your participants (number, age, training status), the protocol (warm-up, test, rest) and the measurements (heart-rate monitor, timing gates, video). Control diet, time of day and prior exercise where you can. Use repeated measures where possible.","Choose a test that fits: paired t-test for before/after on the same people, independent t-test or Mann–Whitney for two groups."],methodMcq:{q:"The same 12 athletes do the sprint with and without a warm-up. Which test compares their times?",opts:["Independent t-test","Paired t-test (or Wilcoxon signed-rank if not normal)","Chi-squared","Spearman"],a:1,why:"Each athlete is measured under both conditions, so the data are paired."},methodRules:[["participant|volunteer|subject|athlete","You describe participants.","Describe your participants."],["heart.rate|monitor|timing|stopwatch|video|measure","You describe measurements.","Say how you measure."]],ethicsRules:[["consent","You plan consent.","Plan informed (and parental) consent."],["withdraw|anonym|confidential","You protect participants.","Include the right to withdraw and anonymity."],["PAR-Q|screen|safe|injur|warm","You plan for safety.","Screen participants (PAR-Q) and plan safe intensity."]],sourceOpts:c("A peer-reviewed study of heart-rate recovery and training status in adolescents"),sourceA:1,data:{guide:["In the pulse simulator choose <b>Less fit volunteer</b>, <b>2 min running</b> and the digital method. Record heart rate at 0–5 minutes after exercise, three runs. Then repeat with the fitter volunteer and compare."],iv:"Time after exercise",ivUnit:"min",dv:"Heart rate",dvUnit:"bpm",levels:[0,1,2,3,4,5],trials:3,test:"spearman",line:!0,example:[[161,162,160],[126,126,128],[107,104,106],[95,94,95],[86,85,85],[83,81,84]]},ex:{rq:"To what extent does training status (trained vs untrained 16–18-year-olds) affect heart-rate recovery in the five minutes after a 2-minute step test?",rqNote:"A defined population, a standard protocol and a measurable outcome.",method:"Ten trained (≥ 4 sessions a week) and ten untrained volunteers, screened with a PAR-Q and with written consent, completed a 2-minute step test (30 cm, 30 steps min⁻¹). Heart rate was recorded with a chest-strap monitor at the end and every minute for 5 minutes, seated. A pilot in the pulse simulator set the time points.",methodNote:"Participants, protocol, measurement and ethics are all clear.",discussion:"Heart rate fell faster in trained participants: one minute after exercise it had dropped by 54 ± 6 bpm compared with 36 ± 9 bpm in untrained participants (Welch’s t-test, p < 0.001). This is consistent with greater parasympathetic reactivation and a larger stroke volume in trained athletes (Daanen et al., 2012). However, the groups were small and not matched for body mass, so the difference may be partly due to other factors."}});var n=function(e){e.group="Practice",e.minutes=e.minutes||30,g.push(e)};n({id:"pr-choose-test",title:"Choosing a statistical test",summary:"Match investigations to the right test, with reasons. Worked examples for t-tests, ANOVA, chi-squared and correlation.",sections:[{title:"The decision",guide:["Ask three questions. <b>1.</b> Am I comparing groups or looking for a relationship? <b>2.</b> How many groups, and are they independent or paired? <b>3.</b> Are the data measurements (normal or skewed) or counts in categories?","Two independent groups → t-test (Welch’s) or Mann–Whitney U if skewed. Same individuals measured twice → paired t-test or Wilcoxon. Three or more groups → one-way ANOVA or Kruskal–Wallis. Counts in categories → chi-squared. Relationship between two numerical variables → Pearson (linear, normal) or Spearman (ranked, monotonic)."],example:{title:"Worked example",text:"Leaf area of 30 dandelions in sun and 30 in shade, roughly normal → two independent groups of measurements → Welch’s t-test. H₀: no difference in mean leaf area."},tasks:[{type:"classify",k:"match",q:"Choose the best test for each investigation.",cats:["t-test","ANOVA","Chi-squared","Spearman / Pearson","Paired t-test"],items:[["Mean mass of snails on two different beaches",0],["Germination rate at five temperatures, five dishes each",1],["Numbers of tall and short offspring compared with a 3:1 ratio",2],["Light intensity and number of plant species in 20 quadrats",3],["Reaction time of the same 15 students before and after caffeine",4],["Presence or absence of lichen on north- and south-facing walls",2]],why:"Correct."},{type:"mcq",k:"m1",q:"Why not use several t-tests instead of one ANOVA for five groups?",opts:["t-tests cannot compare means.","Each test has a 5 % chance of a false positive, so ten tests make a false positive likely.","ANOVA is easier to calculate.","There is no reason."],a:1,why:"Ten pairwise tests at p = 0.05 give roughly a 40 % chance of at least one false positive. ANOVA tests all groups at once; follow up with corrected pairwise tests if significant."},{type:"mcq",k:"m2",q:"A Spearman test gives rₛ = 0.82, p = 0.003. What can you conclude?",opts:["X causes Y.","There is a significant strong positive correlation; it does not show cause.","There is no relationship.","82 % of Y is explained by X."],a:1,why:"Correlation shows association. Cause needs a controlled experiment or a mechanism supported by other evidence."}]}]}),n({id:"pr-descriptive",title:"Mean, standard deviation and uncertainty",summary:"Calculate mean, SD, half range and percentage uncertainty, with worked answers you can reveal.",sections:[{title:"Calculate",guide:["Data: the mass gained by five potato cylinders, in g: <b>12.1, 12.6, 11.9, 12.4, 12.3</b>.","Mean = Σx ÷ n. SD (sample) = √[Σ(x − mean)² ÷ (n − 1)]. Uncertainty of the mean as ± half the range = (max − min) ÷ 2. Percentage uncertainty = uncertainty ÷ mean × 100."],tasks:[{type:"num",k:"mean",q:"Mean mass gained",unit:"g",a:function(e,t){return t.mean([12.1,12.6,11.9,12.4,12.3])},work:function(){return"(12.1 + 12.6 + 11.9 + 12.4 + 12.3) ÷ 5 = 61.3 ÷ 5 = 12.26 g"}},{type:"num",k:"sd",q:"Sample standard deviation",unit:"g",a:function(e,t){return t.sd([12.1,12.6,11.9,12.4,12.3])},hint:"Deviations from 12.26: −0.16, 0.34, −0.36, 0.14, 0.04. Square them, add, divide by 4, square root.",work:function(e,t){return"Σ(x − mean)² = 0.0256 + 0.1156 + 0.1296 + 0.0196 + 0.0016 = 0.292; 0.292 ÷ 4 = 0.073; √0.073 = "+t.sig(t.sd([12.1,12.6,11.9,12.4,12.3]),3)+" g"}},{type:"num",k:"half",q:"Uncertainty of the mean (± half the range)",unit:"g",a:function(){return .35},tol:.001,work:function(){return"(12.6 − 11.9) ÷ 2 = 0.35 g"}},{type:"num",k:"pct",q:"Percentage uncertainty of the mean",unit:"%",a:function(){return .35/12.26*100},tol:.05,work:function(){return"0.35 ÷ 12.26 × 100 = 2.9 %"}},{type:"mcq",k:"dp",q:"The balance reads to 0.1 g. How should you report the mean?",opts:["12.26 g","12.3 ± 0.4 g","12 g","12.260 g"],a:1,why:"Round the uncertainty to one significant figure (0.35 → 0.4) and the mean to the same decimal place (12.3)."}]}]}),n({id:"pr-ttest",title:"A t-test step by step",summary:"Compare two groups with Welch’s t-test: means, SDs, t, degrees of freedom and the decision about H₀.",sections:[{title:"Two groups",guide:["Chlorophyll content (arbitrary units) of leaves from <b>shade</b>: 4.2, 4.8, 5.1, 4.6, 4.9 and <b>sun</b>: 5.6, 6.1, 5.8, 6.4, 5.9.","Welch’s t = (mean₁ − mean₂) ÷ √(s₁²/n₁ + s₂²/n₂). Compare p with 0.05."],tasks:[{type:"num",k:"m1",q:"Mean of the shade leaves",a:function(e,t){return t.mean([4.2,4.8,5.1,4.6,4.9])},work:function(){return"23.6 ÷ 5 = 4.72"}},{type:"num",k:"m2",q:"Mean of the sun leaves",a:function(e,t){return t.mean([5.6,6.1,5.8,6.4,5.9])},work:function(){return"29.8 ÷ 5 = 5.96"}},{type:"num",k:"t",q:"The size of t (ignore the sign)",a:function(e,t){return Math.abs(t.tTest([4.2,4.8,5.1,4.6,4.9],[5.6,6.1,5.8,6.4,5.9]).stat)},tol:.05,hint:"s₁ ≈ 0.342, s₂ ≈ 0.305.",work:function(e,t){return"t = (5.96 − 4.72) ÷ √(0.342²/5 + 0.305²/5) = 1.24 ÷ 0.205 = "+t.sig(Math.abs(t.tTest([4.2,4.8,5.1,4.6,4.9],[5.6,6.1,5.8,6.4,5.9]).stat),3)}},{type:"mcq",k:"dec",q:"The p-value is about 0.0003. What is the decision?",opts:["Accept H₀: there is no difference.","Reject H₀: the mean chlorophyll content differs significantly between sun and shade leaves.","The result proves sunlight causes more chlorophyll.","The test is invalid."],a:1,why:"p < 0.05, so reject H₀. The difference is significant; the explanation (light regulating chlorophyll synthesis) comes from biology, not from the test."}]}]}),n({id:"pr-chi",title:"Chi-squared in genetics",summary:"Test whether offspring ratios fit a Mendelian prediction: expected values, χ², degrees of freedom and the critical value.",sections:[{title:"A monohybrid cross",guide:["A cross between two heterozygous tall pea plants gave <b>290 tall</b> and <b>110 short</b> offspring (400 in total). Mendel predicts 3 tall : 1 short.","χ² = Σ (O − E)² ÷ E. Degrees of freedom = number of categories − 1. Critical value at p = 0.05, 1 df = 3.84."],tasks:[{type:"num",k:"et",q:"Expected number of tall plants",a:function(){return 300},tol:.01,work:function(){return"400 × 3/4 = 300"}},{type:"num",k:"es",q:"Expected number of short plants",a:function(){return 100},tol:.01,work:function(){return"400 × 1/4 = 100"}},{type:"num",k:"chi",q:"χ²",a:function(){return 100/300+100/100},tol:.01,work:function(){return"(290 − 300)²/300 + (110 − 100)²/100 = 0.333 + 1.000 = 1.33"}},{type:"mcq",k:"dec",q:"χ² = 1.33 with 1 degree of freedom (critical value 3.84). Conclusion?",opts:["The results differ significantly from 3:1.","There is no significant difference from 3:1, so the data support Mendel’s prediction.","The cross was not monohybrid.","More data would prove 3:1."],a:1,why:"χ² is below the critical value (p > 0.05), so the differences from 3:1 are likely due to chance."}]}]}),n({id:"pr-spearman",title:"Spearman rank correlation by hand",summary:"Rank two variables, find d², calculate rₛ and interpret it.",sections:[{title:"Rank and calculate",guide:["Distance from a road (m): 2, 4, 6, 8, 10, 12. Lichen cover (%): 3.1, 4.0, 5.2, 4.9, 6.8, 7.5.","Rank each variable (1 = smallest), find d = rank difference for each pair, then rₛ = 1 − 6Σd² ÷ [n(n² − 1)]."],example:{title:"Ranks",table:[["Distance","Rank","Cover","Rank","d","d²"],["2","1","3.1","1","0","0"],["4","2","4.0","2","0","0"],["6","3","5.2","4","−1","1"],["8","4","4.9","3","1","1"],["10","5","6.8","5","0","0"],["12","6","7.5","6","0","0"]]},tasks:[{type:"num",k:"d2",q:"Σd²",a:function(){return 2},tol:.01},{type:"num",k:"rs",q:"rₛ (to 3 decimal places)",a:function(){return 1-12/210},tol:.002,work:function(){return"1 − (6 × 2) ÷ (6 × 35) = 1 − 12/210 = 0.943"}},{type:"mcq",k:"int",q:"The critical value for n = 6 at p = 0.05 is 0.886. Interpretation?",opts:["No significant correlation.","A significant strong positive correlation: lichen cover increases with distance from the road.","Distance from the road causes lichen growth.","A negative correlation."],a:1,why:"rₛ = 0.943 > 0.886, so it is significant. A likely explanation (less air pollution further from traffic) needs supporting evidence."}]}]}),n({id:"pr-graphs",title:"Graphs and error bars",summary:"Choose the right graph, label it properly and interpret error bars.",sections:[{title:"Choosing and reading graphs",guide:["Numerical IV and DV → scatter graph (with a line or curve of best fit if justified). Categories → bar chart. Distribution of one variable → histogram or box plot. Always: title with figure number, axis labels with quantity and unit, sensible scale, error bars with a caption saying what they show."],tasks:[{type:"classify",k:"g",q:"Which graph fits each data set?",cats:["Scatter graph","Bar chart","Histogram or box plot"],items:[["Rate of reaction at seven temperatures",0],["Mean height of bean plants under four colours of light",1],["The spread of 60 leaf lengths from one tree",2],["Heart rate at each minute after exercise",0],["Number of invertebrate species in three habitats",1]],why:"Correct."},{type:"mcq",k:"cap",q:"What should the caption say about error bars?",opts:["Nothing.","What they represent (for example ± 1 SD of five trials).","That they are accurate.","The colour used."],a:1,why:"Readers need to know whether bars show SD, SE, range or a 95 % confidence interval."},{type:"mcq",k:"line",q:"Your points rise and then level off. Which line is appropriate?",opts:["A straight line through the origin","A smooth curve of best fit","Join the dots with straight lines","No line, ever"],a:1,why:"Draw the shape the data and theory support. Joining dots suggests you know values between points."}]}]}),n({id:"pr-evaluation",title:"Writing a strong evaluation",summary:"Classify weaknesses, judge their effect and write specific improvements. Feedback as you type.",sections:[{title:"From weak to strong",guide:["A strong evaluation point has three parts: the weakness, how much it affects the conclusion, and a specific, realistic improvement."],example:{title:"Weak and strong",text:["<b>Weak:</b> “We could have done more repeats and been more careful.”","<b>Strong:</b> “The 10 °C interval meant the optimum could lie anywhere between 30 and 50 °C (a moderate effect on the conclusion). Testing at 35, 40 and 45 °C, with five repeats each, would locate it to within 5 °C.”"]},tasks:[x,{type:"text",k:"ev",label:"Rewrite this weak point as a strong one: “The temperature was not controlled well.”",min:35,rules:[["°C|degree|\\d","You quantify the problem.","Quantify it (how much did the temperature vary?)."],["affect|effect|major|minor|moderate|rate","You explain the effect on the results.","Explain the effect on the results and conclusion."],["water bath|thermostat|monitor|thermometer|insulat","Your improvement is specific.","Give a specific improvement (e.g. a thermostatic water bath at 25.0 ± 0.5 °C)."]]}]}]}),n({id:"pr-ee-question",title:"EE: focusing your question and choosing a pathway",summary:"Sort research questions from too broad to focused, and match topics to subjects before you commit to an EE.",sections:[{title:"Focus",guide:["A focused EE question can be answered in 4,000 words with a method you can carry out, and invites an argument. “To what extent…”, “How effective…” and “How does X affect Y in Z…” are good starts."],tasks:[{type:"classify",k:"f",q:"Sort these questions.",cats:["Too broad","Focused and arguable","Too narrow or descriptive"],items:[["How does pollution affect the environment?",0],["To what extent does distance from a cement factory affect lichen diversity on tree trunks in Athi River?",1],["What colour is chlorophyll?",2],["How does sugar affect health?",0],["How effective is garlic extract (0–100 %) at inhibiting the growth of a school-safe strain of E. coli compared with a commercial antiseptic?",1],["When was DNA discovered?",2]],why:"Correct."},{type:"classify",k:"s",q:"Which subject fits each idea best?",cats:["Biology","Chemistry","Physics","ESS","SEHS"],items:[["Enzyme activity in pineapple at different temperatures",0],["Enthalpy of combustion of alcohols",1],["Terminal velocity of falling cupcake cases",2],["Plastic waste on beaches and local attitudes to a ban",3],["Effect of a warm-up on sprint performance",4]],why:"Correct."}]}]}),n({id:"pr-ee-sources",title:"EE: sources and analytical writing",summary:"Judge sources and turn descriptive sentences into analytical ones.",sections:[{title:"Sources and argument",guide:["Evaluate a source by its author and expertise, where it was published (peer review), date, method and possible bias. In writing, description says what happened; analysis says what it means and how strong the evidence is."],tasks:[{type:"classify",k:"d",q:"Descriptive or analytical?",cats:["Descriptive","Analytical"],items:[["The rate was 5.6 at pH 7.",0],["The rate peaked at pH 7, which suggests the active site’s charges are optimal near neutrality, consistent with Urry et al. (2020).",1],["I used five repeats.",0],["Because the SDs at each pH were below 2 % of the mean, the trend is unlikely to be due to random error.",1]],why:"Correct. Analytical sentences explain, link and judge."},{type:"mcq",k:"src",q:"A company selling fertiliser publishes a study showing its product doubles yield. How should you treat it?",opts:["As the strongest evidence.","With caution: possible bias; look for independent peer-reviewed studies and check its method.","Ignore all company research.","Cite it without comment."],a:1,why:"Funding can bias results. Use it if relevant, but say so and compare with independent work."},{type:"text",k:"rw",label:"Rewrite as analysis: “The bean plants in red light grew 12 cm and those in green light grew 5 cm.”",min:30,rules:[["because|suggest|absorb|chlorophyll|photosynth","You explain the difference.","Explain why (which wavelengths chlorophyll absorbs)."],["however|although|may|likely|limitation","You judge the evidence.","Judge how strong the evidence is."]]}]}]})})();
